# Generated by manage.py generate_test_cases.
from bloomerp.models.tutorial import Tutorial, TutorialTopic
from bloomerp.tests.base import BloomerpModelTestCase, ModelScenario


class TestTutorialTopicModel(BloomerpModelTestCase):
    model = TutorialTopic

    def assign_topics(self, topic: TutorialTopic) -> None:
        """Assign a shared topic and give a tutorial a second topic."""
        self.bulk_upload = Tutorial.objects.create(name="Bulk uploads")
        self.search = Tutorial.objects.create(name="Search")
        self.data_management = TutorialTopic.objects.create(
            name="Data management", sequence=20
        )
        self.bulk_upload.topics.add(self.data_management, topic)
        self.search.topics.add(topic)

    def has_ordered_assignments(self, topic: TutorialTopic) -> bool:
        """Verify both directions of the assignment and the topic ordering."""
        return list(self.bulk_upload.topics.all()) == [
            topic,
            self.data_management,
        ] and set(topic.tutorials.all()) == {self.bulk_upload, self.search}

    def get_test_scenarios(self) -> list[ModelScenario[TutorialTopic]]:
        """Exercise the ordered many-to-many relationship used by the catalog."""
        return [
            ModelScenario(
                name="Tutorials can share topics and list them in display order",
                create_args={
                    "name": "Getting started",
                    "description": "Learn the basics.",
                    "sequence": 10,
                },
                post_create=self.assign_topics,
                create_validators=self.has_ordered_assignments,
            ),
        ]
